import {mobility,spectra,stix,quote,bikeDemo,spectrumDemo,stixDemo} from './core.mjs';
const $=id=>document.getElementById(id), fmt=(v,d=0)=>new Intl.NumberFormat('es-MX',{maximumFractionDigits:d,minimumFractionDigits:d}).format(v), money=v=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(v);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const repo='https://github.com/JuanSeCe1402/juan-serena-data-science';
let active='',report=null,revision=0;
const defs={
 cortex:{category:'01 / APLICACIONES + COSTOS',title:'Cortex 3D',desc:'Calcula el costo de una impresión y construye un precio con recargo o margen sobre ventas.',slug:'cortex-impresion-3d',method:[['Modelo de costos','Material + electricidad + operación por hora + otros costos por trabajo. El desglose distingue costo, utilidad e impuesto.'],['Recargo ≠ margen','Recargo: precio = costo × (1 + porcentaje). Margen: precio = costo ÷ (1 − porcentaje). El impuesto se añade después.'],['Alcance','Estimación para planificación, en MXN. Las tarifas son editables; no incluye pérdidas, comisiones u obligaciones fiscales no capturadas.']]},
 movilidad:{category:'02 / ANALÍTICA DE DATOS',title:'Movilidad urbana',desc:'De un CSV de viajes a patrones por hora, duración media y estaciones de origen.',slug:'movilidad-urbana',method:[['Entrada','CSV UTF-8 con Start Time y Trip Duration. Fechas YYYY-MM-DD HH:mm:ss y duración en segundos. User Type y Start Station son opcionales.'],['Transformación','Se descartan fechas inválidas y duraciones negativas, vacías o no finitas. Se agregan horas tal como aparecen en el archivo, sin convertir zona horaria.'],['Alcance','La media no describe toda la distribución ni establece causalidad. La demo usa 240 viajes ficticios y no representa una ciudad real.']]},
 espectros:{category:'03 / SEÑALES + FÍSICA',title:'Espectros ópticos',desc:'Inspecciona una señal instrumental, localiza su máximo global y exporta sus métricas.',slug:'espectros-opticos',method:[['Entrada','CSV con dos primeras columnas numéricas X e Y. Tolera filas de metadatos, coma o punto y coma; usa punto decimal. Hasta 200 mil pares.'],['Transformación','Se conservan pares finitos y se ordenan por X. El gráfico reduce puntos solo para visualizar; las métricas se calculan con todos los pares válidos.'],['Alcance','El máximo es matemático, no una identificación física. Las unidades deben comprobarse en el instrumento. No se realizan calibración, suavizado o diagnóstico.']]},
 stix:{category:'04 / CIBERSEGURIDAD + DATOS',title:'Indicadores STIX',desc:'Explora bundles JSON y diferencia objetos, identificadores únicos y patrones repetidos.',slug:'indicadores-stix',method:[['Entrada','Uno o varios archivos JSON/STIX con una lista objects. Se procesan juntos para encontrar repeticiones entre colecciones.'],['Transformación','Se cuentan tipos y se comparan IDs y patrones exactamente como texto. No se interpretan expresiones STIX ni se consultan direcciones o dominios.'],['Alcance','Patrones distintos pueden ser semánticamente equivalentes. Este análisis no identifica amenazas activas ni evalúa la seguridad de un dispositivo.']]}
};
function metrics(items){return '<div class="metrics">'+items.map(([label,value,unit=''])=>`<div class="metric"><small>${esc(label)}</small><strong>${esc(value)} <span class="unit">${esc(unit)}</span></strong></div>`).join('')+'</div>';}
function table(title,headers,rows){return `<div><div class="chart-title"><h3>${esc(title)}</h3></div><table class="simple-table"><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function bars(values,labels,title){const w=660,h=215,left=36,bottom=28,top=15,max=Math.max(...values,1),bw=(w-left-10)/values.length;return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)}"><line x1="${left}" y1="${h-bottom}" x2="${w}" y2="${h-bottom}" stroke="#d8dfd6"/>${[0,.5,1].map(f=>`<line x1="${left}" y1="${h-bottom-(h-bottom-top)*f}" x2="${w}" y2="${h-bottom-(h-bottom-top)*f}" stroke="#e9ede6"/><text x="1" y="${h-bottom-(h-bottom-top)*f+4}">${fmt(max*f)}</text>`).join('')}${values.map((v,i)=>`<rect x="${left+i*bw+2}" y="${h-bottom-v/max*(h-bottom-top)}" width="${Math.max(2,bw-5)}" height="${v/max*(h-bottom-top)}" fill="${v===Math.max(...values)?'#245a59':'#a7bea9'}" rx="2"><title>${esc(labels[i])}: ${fmt(v)}</title></rect>${values.length<12||i%3===0?`<text x="${left+(i+.5)*bw}" y="${h-8}" text-anchor="middle">${esc(labels[i])}</text>`:''}`).join('')}</svg>`;}
function signalChart(result){const {points,xMin,xMax,yMin,yMax}=result,w=660,h=265,l=55,r=15,b=35,t=15;const x=v=>l+(v-xMin)/(xMax-xMin||1)*(w-l-r),y=v=>h-b-(v-yMin)/(yMax-yMin||1)*(h-b-t);const stride=Math.max(1,Math.ceil(points.length/1200));let shown=points.filter((_,i)=>i%stride===0);shown.push(points.at(-1));let path=shown.map((p,i)=>`${i?'L':'M'}${x(p[0]).toFixed(2)},${y(p[1]).toFixed(2)}`).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Señal óptica. Máximo global en X ${esc(fmt(result.peak[0],3))}">${[0,.5,1].map(f=>{const val=yMin+(yMax-yMin)*f;return `<line x1="${l}" x2="${w-r}" y1="${y(val)}" y2="${y(val)}" stroke="#e5ebe1"/><text x="3" y="${y(val)+4}">${esc(fmt(val,2))}</text>`}).join('')}<path d="${path}" fill="none" stroke="#245a59" stroke-width="2"/><circle cx="${x(result.peak[0])}" cy="${y(result.peak[1])}" r="4" fill="#9db65f"/>${[xMin,(xMin+xMax)/2,xMax].map(v=>`<text text-anchor="middle" x="${x(v)}" y="${h-12}">${esc(fmt(v,2))}</text>`).join('')}</svg>`;}
function showError(e){$('error').textContent=e.message||String(e);$('error').hidden=false;}
function clearError(){$('error').hidden=true;$('error').textContent='';}
function source(label){$('source-badge').textContent=label;}
function saveReport(slug,origin,metrics){report={project:slug,origin,createdAt:new Date().toISOString(),...metrics};$('download').disabled=false;}
function showMobility(text,label){const r=mobility(text);$('result-content').innerHTML=metrics([['VIAJES VÁLIDOS',fmt(r.valid)],['DURACIÓN MEDIA',fmt(r.averageSeconds/60,1),'min'],['FILAS DESCARTADAS',fmt(r.rejected)]])+`<div class="chart-title"><h3>¿A qué hora comienzan los viajes?</h3><span>Hora del archivo · 00–23 h</span></div>`+bars(r.hours,r.hours.map((_,i)=>String(i).padStart(2,'0')),'Viajes por hora')+'<div class="two-cols">'+table('Estaciones principales',['Origen','Viajes'],r.stations.map(([s,v])=>[s,fmt(v)]))+table('Tipos de usuario',['Tipo','Viajes'],r.types.map(([s,v])=>[s,fmt(v)]))+'</div>'+`<details class="note"><summary>Ver conteos horarios accesibles</summary>${table('Distribución horaria',['Hora','Viajes'],r.hours.map((n,i)=>[`${i}:00`,fmt(n)]))}</details><p class="note">${fmt(r.uniqueStations)} etiquetas de estación distintas. Se muestran hasta seis estaciones y tipos de usuario. Revisa las filas descartadas antes de interpretar.</p>`;source(label);saveReport('movilidad',label,r);}
function showSpectra(text,label){const r=spectra(text);$('result-content').innerHTML=metrics([['PARES VÁLIDOS',fmt(r.count)],['X DEL MÁXIMO',fmt(r.peak[0],3)],['AMPLITUD MÁXIMA',fmt(r.peak[1],3)]])+`<div class="chart-title"><h3>Señal ordenada por X</h3><span>Unidades según instrumento</span></div>`+signalChart(r)+table('Resumen de la señal',['Métrica','Valor'],[['Intervalo X',`${fmt(r.xMin,3)} → ${fmt(r.xMax,3)}`],['Intervalo Y',`${fmt(r.yMin,3)} → ${fmt(r.yMax,3)}`],['Filas no numéricas o inválidas',fmt(r.discarded)]])+`<p class="note">El máximo global no equivale a una detección de todos los picos. El gráfico puede reducir puntos para visualizar; el reporte usa todos los datos válidos.</p>`;source(label);const {points,...summary}=r;saveReport('espectros',label,summary);}
function showStix(bundles,label){const r=stix(bundles);$('result-content').innerHTML=metrics([['OBJETOS TOTALES',fmt(r.total)],['INDICADORES',fmt(r.indicators)],['PATRONES REPETIDOS',fmt(r.repeatedPatterns)]])+`<div class="chart-title"><h3>Tipos de objeto</h3><span>Conteos de objetos, no entidades únicas</span></div>`+(r.types.length?bars(r.types.map(x=>x[1]),r.types.map(x=>x[0]),'Objetos STIX por tipo'):'<p class="note">El bundle está vacío.</p>')+'<div class="two-cols">'+table('Calidad de los indicadores',['Métrica','Conteo'],[['IDs únicos',fmt(r.uniqueIds)],['Patrones únicos',fmt(r.uniquePatterns)],['Sin ID',fmt(r.missingId)],['Sin patrón',fmt(r.missingPattern)]] )+table('Tipos de patrón detectados',['Objeto observable','Indicadores'],r.kinds.map(([s,v])=>[s,fmt(v)]))+'</div><p class="note">La deduplicación compara texto exacto. No se visitan dominios, no se ejecutan patrones y no se realizan comprobaciones de amenazas.</p>';source(label);saveReport('stix',label,r);}
function costForm(){return `<h2>Parámetros del trabajo</h2><p>Valores de ejemplo editables · MXN</p><form id="cost-form"><div class="form-row"><label>Peso (g)<input name="grams" type="number" min="0.01" step="any" value="125" required></label><label>Tiempo (h)<input name="hours" type="number" min="0.01" step="any" value="4.5" required></label></div><div class="form-row"><label>Material ($/kg)<input name="priceKg" type="number" min="0" step="any" value="300" required></label><label>Potencia (W)<input name="watts" type="number" min="0" step="any" value="120" required></label></div><div class="form-row"><label>Electricidad ($/kWh)<input name="kwh" type="number" min="0" step="any" value="3.2" required></label><label>Operación ($/h)<input name="hourly" type="number" min="0" step="any" value="8" required></label></div><label>Otros costos por trabajo ($)<input name="extra" type="number" min="0" step="any" value="5" required></label><label>Cómo calcular la utilidad<select name="mode"><option value="markup">Recargo sobre costo</option><option value="margin">Margen sobre ventas</option></select></label><div class="form-row"><label>Porcentaje (%)<input name="percent" type="number" min="0" max="1000" step="any" value="35" required></label><label>Impuesto (%)<input name="tax" type="number" min="0" max="100" step="any" value="16" required></label></div><button class="btn primary" type="submit">Calcular cotización →</button></form>`;}
function showCost(){clearError();try{const form=$('cost-form');const data=Object.fromEntries(new FormData(form));for(const k of Object.keys(data))if(k!=='mode')data[k]=Number(data[k]);const r=quote(data);const parts=[['Material',r.material,'#245a59'],['Electricidad',r.electricity,'#abc5ad'],['Operación',r.operation,'#72899a'],['Otros',r.extra,'#b5b6a1'],['Utilidad',r.profit,'#cce08a']];$('result-content').innerHTML=`<div class="quote-total"><div><span>COTIZACIÓN ESTIMADA</span><small>Pesos mexicanos · impuestos incluidos</small></div><strong>${esc(money(r.total))}</strong></div>`+metrics([['COSTO BASE',money(r.base)],['UTILIDAD SIN IMPUESTO',money(r.profit)],['MARGEN EFECTIVO',fmt(r.actualMargin,1),'%']])+`<div class="chart-title"><h3>Del costo al precio</h3><span>Subtotal: ${esc(money(r.subtotal))}</span></div><div class="breakdown-bar" role="img" aria-label="Desglose del subtotal">${parts.map(([label,v,color])=>`<span style="width:${r.subtotal?v/r.subtotal*100:0}%;background:${color}" title="${label}: ${money(v)}"></span>`).join('')}</div>`+table('Detalle de la estimación',['Concepto','Importe'],[...parts.map(([label,v])=>[label,money(v)]),['Subtotal',money(r.subtotal)],[`Impuesto (${fmt(data.tax,2)} %)`,money(r.tax)],['Total',money(r.total)]])+`<p class="note">Consumo estimado: ${fmt(r.kwhUsed,3)} kWh. ${data.mode==='markup'?'El porcentaje es un recargo sobre costo.':'El porcentaje es un margen sobre ventas antes de impuestos.'} La utilidad no incluye costos que no hayas capturado. Estimación, no factura.</p>`;source('ESTIMACIÓN · PARÁMETROS EDITABLES');saveReport('cortex','Parámetros ingresados',{inputs:data,result:r});}catch(e){showError(e);}}
function uploadPanel(kind){const config={movilidad:['viajes CSV','.csv,text/csv','Start Time, Trip Duration\nStart Station, User Type (opcionales)'],espectros:['espectro CSV','.csv,text/csv','X,Y\n1549.0,0.4\n1550.0,1.8'],stix:['bundles JSON / STIX','.json,.stix,.stix2,application/json','{"type":"bundle","objects":[…]}']}[kind];return `<h2>Explora tus datos</h2><p>Empieza con un ejemplo o carga ${config[0]}. Máximo 50 MB en total.</p><button class="btn primary" id="load-demo">Cargar demo sintética ↻</button><button class="small-btn" style="width:100%;margin-top:10px" id="sample-download">Descargar archivo de ejemplo ↓</button><label class="upload-label">Seleccionar ${kind==='stix'?'archivos':'archivo'}<input id="file-input" type="file" accept="${config[1]}" ${kind==='stix'?'multiple':''}></label><p class="schema">${esc(config[2])}</p><p id="processing" role="status"></p>`;}
function getDemo(kind){if(kind==='movilidad')return bikeDemo();if(kind==='espectros')return spectrumDemo();return JSON.stringify(stixDemo(),null,2);}
function runDemo(kind){revision++;clearError();if(kind==='movilidad')showMobility(bikeDemo(),'DEMO SINTÉTICA · 240 VIAJES');if(kind==='espectros')showSpectra(spectrumDemo(),'DEMO SINTÉTICA · 301 PARES');if(kind==='stix')showStix([stixDemo()],'DEMO SINTÉTICA · 8 OBJETOS');}
function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function filesChanged(kind,event){const files=[...event.target.files];if(!files.length)return;clearError();const token=++revision;const message=$('processing');const input=event.target;input.disabled=true;const demo=$('load-demo');demo.disabled=true;message.textContent='Leyendo y analizando en tu navegador…';report=null;$('download').disabled=true;$('result-content').classList.add('pending');await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
 try{if(files.reduce((a,f)=>a+f.size,0)>50*1024*1024)throw Error('El total supera 50 MB. Divide los archivos e inténtalo de nuevo.');const texts=[];for(const f of files)texts.push(await f.text());if(token!==revision)return;const label='ARCHIVO LOCAL · '+files.map(f=>f.name).join(', ');if(kind==='movilidad')showMobility(texts[0],label);if(kind==='espectros')showSpectra(texts[0],label);if(kind==='stix'){let parsed;try{parsed=texts.map(t=>JSON.parse(t.replace(/^\uFEFF/,'')));}catch{throw Error('El JSON no es válido. Revisa comas, comillas y el formato del bundle.');}showStix(parsed,label);}message.textContent='Análisis completado.';
 }catch(e){if(token!==revision)return;showError(e);message.textContent='No se pudo completar el análisis.';source('ARCHIVO CON ERROR');$('result-content').innerHTML='<p class="empty">Corrige el archivo o vuelve a cargar la demo.</p>';
 }finally{input.disabled=false;demo.disabled=false;if(token===revision)$('result-content').classList.remove('pending');}}
function route(){revision++;$('result-content').classList.remove('pending');const hash=location.hash.slice(1)||'inicio';const d=defs[hash];$('home').hidden=!!d;$('workspace').hidden=!d;clearError();if(!d){active='inicio';document.title='Juan Serena — Applied Data Lab';return;}active=hash;report=null;document.title=`${d.title} — Juan Serena`;$('app-category').textContent=d.category;$('app-title').textContent=d.title;$('app-description').textContent=d.desc;$('app-source').href=`${repo}/tree/main/proyectos/${d.slug}`;$('method-content').innerHTML='<div class="method-grid">'+d.method.map(([title,text])=>`<div><h3>${title}</h3><p>${text}</p></div>`).join('')+'</div>';$('print').hidden=hash!=='cortex';$('input-content').innerHTML=hash==='cortex'?costForm():uploadPanel(hash);if(hash==='cortex'){$('cost-form').addEventListener('submit',event=>{event.preventDefault();showCost();});showCost();}else{$('load-demo').addEventListener('click',()=>runDemo(hash));$('sample-download').addEventListener('click',()=>download(getDemo(hash),hash==='stix'?'application/json':'text/csv',`demo-sintetica-${hash}.${hash==='stix'?'json':'csv'}`));$('file-input').addEventListener('change',event=>filesChanged(hash,event));runDemo(hash);}window.scrollTo({top:0,behavior:'instant'});}
$('download').addEventListener('click',()=>{if(report)download(JSON.stringify(report,null,2),'application/json',`reporte-${active}.json`);});$('print').addEventListener('click',()=>window.print());window.addEventListener('hashchange',route);route();
